-- ============================================================================
-- PROJETO ERP PETLY CLUB - MASSA DE DADOS HISTÓRICA (VENDAS DE 01/08 A 19/10/2026)
-- ============================================================================
-- Grupo 7 | SGBD: PostgreSQL 16 | Data de referência dos testes: 27/10/2026
-- Pré-requisito: petly_club_ddl_limpo.sql + Massa_de_Dados_Completa_-_ERP_Petly_Club.sql
-- Como rodar:    psql -d petly_club -f Massa_Historico_Vendas_ERP_Petly_Club.sql
--
-- Objetivo: dar ao banco alguns meses de histórico para as consultas gerenciais, os indicadores
-- e a proposta de BI (evolução das vendas, ticket médio, recompra, giro). A massa principal cobre
-- os cenários da seção 17.1; esta cobre o volume. Nenhum registro da massa principal é alterado.
--
-- Como foi gerada: script gerar_massa_historico.py (nesta pasta), escrito com auxílio de IA
-- (Claude) e validado pela equipe. O script simula o estoque dia a dia e só grava o que o banco aceita:
-- - toda saída usa FEFO (RN20): o lote que vence primeiro; os lotes históricos dos produtos 1, 2, 4, 5
--   e 6 vencem antes dos lotes da massa principal e terminam com saldo zero em 19/10;
-- - o antipulgas só vende em outubro, do lote 5, porque o lote 4 venceu em 30/09 (cenário 3);
-- - loja virtual: reserva no pedido e venda no envio ou na retirada (RN21); cancelado libera a reserva;
-- - todo pagamento autorizado gera contas a receber que somam o seu valor (RN24); crédito em até 3x,
--   com taxa de 5%; débito 1,99%; parcela com data prevista até 27/10 está recebida, depois, pendente;
-- - toda compra tem as entradas de tudo que foi comprado e duas parcelas a pagar que somam o total;
-- - desconto só com autorizador (RP05); perda só com motivo e autorizador gerente (RP11).
-- Validação: depois desta carga, os testes de integridade dão o resultado esperado e as 10 consultas
-- de auditoria continuam retornando 0 linhas.
--
-- Conteúdo: 30 clientes, 8 produtos, 6 compras, 26 lotes, 337 pedidos, 741 movimentações de estoque,
-- 337 pagamentos, 395 contas a receber, 71 entregas, 12 contas a pagar e 9 pagamentos de contas.
-- Faixas de id próprias (pedido >= 1001, lote >= 101, compra >= 201...), sem conflito com a massa
-- principal nem com os ids usados nos testes.
-- ============================================================================

